// The gateway's one page for every role (docs/50), on the plain server and the database
// e2e/console_server.py seeded for this run. Each account logs in at /dashboard/, sees exactly the
// navigation its role gives (the table of docs/console-integration-plan.md, section 2.3: kept
// here, in the tests, never in the page), opens each item shown, and is refused one hidden item
// by its address. Then: a deep link from logged out, a session ended from elsewhere, the
// console's old address, and a leak scan of all of it with its planted control. The passwords
// were generated by playwright.config.ts at the start of the run.

import { expect, test, type Browser, type Page, type TestInfo } from "@playwright/test";
import {
  ADMIN,
  APP_ADMIN,
  APP_READER,
  NO_ROLE,
  NOT_AVAILABLE,
  OPERATOR,
  ORG_READER,
  SESSION_ENDED,
  Scan,
  logIn,
  picture,
  secret,
  sections,
  type Account,
  logOut,
} from "./session";

test.describe.configure({ mode: "serial" });

interface Expected {
  account: Account;
  /** The picture's name: the role, as the plan's table names it. */
  name: string;
  navigation: string[];
  /** Where it lands (docs/51): its organization's Applications, or Home. */
  landing: "Applications" | "Home";
  /** The regions inside Home, for a session that lands there. */
  home: (string | RegExp)[];
  hidden: string;
}

const ROLES: Expected[] = [
  {
    account: OPERATOR,
    name: "platform-admin",
    navigation: ["Home", "Monitoring"],
    landing: "Home",
    home: ["Platform", /^Organization /],
    hidden: "#/channels",
  },
  {
    account: ADMIN,
    name: "org-admin",
    navigation: [
      "Home",
      "Applications",
      "Organization settings",
      "Channels",
      "Incidents",
      "Application settings",
      "Alert rules",
      "API keys",
    ],
    landing: "Applications",
    home: [],
    hidden: "#/monitor/overview",
  },
  {
    account: ORG_READER,
    name: "organization-reader",
    navigation: [
      "Home",
      "Applications",
      "Organization settings",
      "Incidents",
      "Application settings",
      "Alert rules",
    ],
    landing: "Applications",
    home: [],
    hidden: "#/channels",
  },
  {
    account: APP_ADMIN,
    name: "app-admin",
    navigation: ["Home", "Incidents", "Application settings", "Alert rules", "API keys"],
    landing: "Home",
    home: ["Your applications"],
    hidden: "#/organization",
  },
  {
    account: APP_READER,
    name: "application-reader",
    navigation: ["Home", "Incidents", "Application settings", "Alert rules"],
    landing: "Home",
    home: ["Your applications"],
    hidden: "#/channels",
  },
  {
    account: NO_ROLE,
    name: "no-role",
    navigation: ["Home"],
    landing: "Home",
    home: ["No access yet"],
    hidden: "#/organization",
  },
];

// --- every role -----------------------------------------------------------------------------------

for (const role of ROLES) {
  test(`${role.name}: exactly its navigation, its home, each item, one refused by address, no leak`, async ({
    page,
  }, testInfo) => {
    const scan = new Scan();
    scan.watch(page);
    await page.goto("/dashboard/");
    await logIn(page, role.account, scan, testInfo);

    await expect(sections(page).getByRole("link")).toHaveText(role.navigation);
    const home = page.getByRole("region", { name: role.landing, exact: true });
    await expect(home).toBeVisible();
    for (const region of role.home) {
      await expect(home.getByRole("region", { name: region, exact: true })).toBeVisible();
    }
    await picture(page, testInfo, `home-${role.name}`);

    // Each item shown opens its screen.
    for (const label of role.navigation.slice(1)) {
      await sections(page).getByRole("link", { name: label, exact: true }).click();
      await expect(page.getByRole("heading", { name: label, level: 2 })).toBeVisible();
      await scan.step(page);
    }

    // One it does not show, opened by its address: where it lands, with one sentence.
    await page.goto(`/dashboard/${role.hidden}`);
    await expect(
      page.getByRole("region", { name: role.landing, exact: true }).getByRole("alert").first(),
    ).toHaveText(NOT_AVAILABLE);
    await scan.step(page);
    await picture(page, testInfo, `hidden-${role.name}`);

    expect(await scan.leaks(page)).toEqual([]);
  });
}

// --- deep links, ended sessions, the old address ----------------------------------------------

async function freshPage(browser: Browser, testInfo: TestInfo): Promise<Page> {
  const context = await browser.newContext({
    baseURL: testInfo.project.use.baseURL,
    viewport: { width: 1400, height: 1000 },
  });
  return context.newPage();
}

test("a deep link from logged out returns to its place after login", async ({
  browser,
}, testInfo) => {
  const page = await freshPage(browser, testInfo);
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/#/rules/app-one");
  await expect(page.getByRole("region", { name: "Log in", exact: true })).toBeVisible();
  await picture(page, testInfo, "login");
  await logIn(page, ADMIN, scan);
  await expect(page.getByRole("heading", { name: "Alert rules", level: 2 })).toBeVisible();
  await expect(page.getByRole("combobox", { name: "Application", exact: true })).toHaveValue(
    "app-one",
  );
  expect(new URL(page.url()).hash).toBe("#/rules/app-one");
  expect(await scan.leaks(page)).toEqual([]);
  await page.context().close();
});

test("a session ended elsewhere sends the page to login, and back to its place", async ({
  browser,
}, testInfo) => {
  const page = await freshPage(browser, testInfo);
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/#/incidents");
  await logIn(page, ADMIN, scan);
  await expect(page.getByRole("heading", { name: "Incidents", level: 2 })).toBeVisible();

  // Another browser holding the same session logs it out: the gateway forgets it.
  const session = (await page.context().cookies()).find((c) => c.name === "gw_session");
  expect(session).toBeDefined();
  const other = await browser.newContext({ baseURL: testInfo.project.use.baseURL });
  if (session !== undefined) await other.addCookies([session]);
  const me = (await (await other.request.get("/v1/auth/me")).json()) as { csrf_token: string };
  const out = await other.request.post("/v1/auth/logout", {
    headers: { "X-CSRF-Token": me.csrf_token },
    data: {},
  });
  expect(out.status()).toBe(200);
  await other.close();

  // The next section the page opens learns it: login, where it was, with the reason.
  await sections(page).getByRole("link", { name: "Channels", exact: true }).click();
  const login = page.getByRole("region", { name: "Log in", exact: true });
  await expect(login).toContainText(SESSION_ENDED);
  expect(new URL(page.url()).hash).toBe("#/channels");
  await picture(page, testInfo, "session-ended");
  await logIn(page, ADMIN, scan);
  await expect(page.getByRole("heading", { name: "Channels", level: 2 })).toBeVisible();
  expect(await scan.leaks(page)).toEqual([]);
  await page.context().close();
});

test("the console's old address opens the same place on the one page", async ({ page }) => {
  await page.goto("/dashboard/console.html#/channels");
  await expect(page).toHaveURL(/\/dashboard\/#\/channels$/);
  await expect(page.getByRole("region", { name: "Log in", exact: true })).toBeVisible();
});

test("logging out leaves the next person at home", async ({ page }) => {
  await page.goto("/dashboard/#/organization");
  await logIn(page, ORG_READER);
  await expect(
    page.getByRole("heading", { name: "Organization settings", level: 2 }),
  ).toBeVisible();
  await logOut(page);
  await expect(page.getByRole("region", { name: "Log in", exact: true })).toContainText(
    "Logged out.",
  );
  expect(new URL(page.url()).hash).toBe("#/home");
});

test("leak scan control: a password planted in storage and in the address is found", async ({
  page,
}) => {
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/");
  await logIn(page, ORG_READER, scan);
  expect(await scan.leaks(page)).toEqual([]);

  // Planted by this test, not the page: a value made from the password, in session storage and
  // in the URL's fragment. The scan must find both, or it could not be trusted to find a leak.
  const marker = `planted-${secret(ORG_READER.second)}`;
  await page.evaluate((value) => {
    sessionStorage.setItem("planted", value);
    window.location.hash = `#/${encodeURIComponent(value)}`;
  }, marker);
  // The organization's reader lands on its Applications (docs/51).
  await expect(
    page.getByRole("region", { name: "Applications", exact: true }).getByRole("alert").first(),
  ).toHaveText(NOT_AVAILABLE);
  const found = await scan.leaks(page);
  expect(found).toContainEqual(["session storage", ORG_READER.second]);
  expect(found).toContainEqual(["urls", ORG_READER.second]);
  await page.evaluate(() => {
    sessionStorage.removeItem("planted");
  });
});
